const products=[{name:'الكلاسيكي',description:'لفّة القرفة الأصلية مع صوص كريمي. الطعم الذي تحبّه، كما هو.',x:38},{name:'كراميل بيكان',description:'كراميل غني وقطع بيكان محمّصة. حلاوة وقرمشة في كل لقمة.',x:280},{name:'شوكولاتة لوتس',description:'شوكولاتة لذيذة مع بسكويت لوتس المقرمش. مزيج يستحق التجربة.',x:525},{name:'نوتيلا',description:'نوتيلا غنية مع قطع البندق المقرمشة. لمحبي الشوكولاتة.',x:765}];
const quantities=products.map(()=>0);const form=document.getElementById('order-form');
document.getElementById('products').innerHTML=products.map((p,i)=>`<article class="product-card"><svg viewBox="${p.x} 1050 220 175" role="img" aria-label="${p.name} من صورة المتجر الدعائية"><image href="assets/collection.jpeg" width="1024" height="1536"/></svg><div class="product-content"><h3>${p.name}</h3><p>${p.description}</p><div class="quantity"><span>عدد القطع</span><div class="counter"><button type="button" data-index="${i}" data-delta="-1" aria-label="تقليل كمية ${p.name}">−</button><input type="number" min="0" max="999" step="1" value="0" data-quantity="${i}" aria-label="عدد قطع ${p.name}"><button type="button" data-index="${i}" data-delta="1" aria-label="زيادة كمية ${p.name}">+</button></div></div></div></article>`).join('');
function localDate(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;}form.elements.date.min=localDate();
function message(){const data=new FormData(form);const lines=products.flatMap((p,i)=>quantities[i]?[`• ${p.name} × ${quantities[i]} قطعة`]:[]);return ['مرحبًا Dana Sweets، أرغب في طلب:',...lines,`إجمالي القطع: ${quantities.reduce((a,b)=>a+b,0)}`,`الاسم: ${String(data.get('customer')||'').trim()||'—'}`,`العنوان في جدة: ${String(data.get('address')||'').trim()||'—'}`,`التاريخ المطلوب: ${data.get('date')||'—'}`,...(String(data.get('notes')||'').trim()?[`ملاحظات: ${String(data.get('notes')).trim()}`]:[]),'أرجو تأكيد التوفر والسعر وأحجام العبوات وموعد ورسوم التوصيل. شكرًا!'].join('\n');}
function refresh(){const total=quantities.reduce((a,b)=>a+b,0);document.getElementById('cart-count').textContent=total;const box=document.getElementById('order-items');box.replaceChildren();if(!total){box.textContent='لم تختر النكهات بعد. أضف الكميات من بطاقات المنتجات.';}else{products.forEach((p,i)=>{if(quantities[i]){const line=document.createElement('p');line.textContent=`${p.name} × ${quantities[i]} قطعة`;box.append(line);}});const sum=document.createElement('strong');sum.textContent=`المجموع: ${total} قطعة`;box.append(sum);}document.getElementById('message-preview').textContent=message();}
document.getElementById('products').addEventListener('click',event=>{const button=event.target.closest('button[data-index]');if(!button)return;const i=Number(button.dataset.index);quantities[i]=Math.max(0,Math.min(999,quantities[i]+Number(button.dataset.delta)));document.querySelector(`[data-quantity="${i}"]`).value=quantities[i];document.getElementById('form-status').textContent='';refresh();});
document.getElementById('products').addEventListener('change',event=>{if(!event.target.matches('[data-quantity]'))return;const i=Number(event.target.dataset.quantity);quantities[i]=Math.max(0,Math.min(999,Math.trunc(Number(event.target.value)||0)));event.target.value=quantities[i];refresh();});form.addEventListener('input',refresh);
form.addEventListener('submit',event=>{event.preventDefault();const status=document.getElementById('form-status');if(!quantities.some(Boolean)){status.textContent='اختر قطعة واحدة على الأقل من النكهات أعلاه.';document.getElementById('flavors').scrollIntoView({behavior:'smooth'});document.querySelector('[data-quantity]').focus({preventScroll:true});return;}if(!form.elements.customer.value.trim()||form.elements.address.value.trim().length<8){status.textContent='يرجى كتابة الاسم وعنوان واضح للطلب.';return;}form.elements.date.min=localDate();if(!form.checkValidity()){form.reportValidity();return;}const url=`https://wa.me/966507448979?text=${encodeURIComponent(message())}`;status.textContent='الرسالة جاهزة. أرسلها في واتساب ليؤكد المتجر طلبك.';window.open(url,'_blank','noopener,noreferrer');});refresh();
